# Auto-concurrency is deliberately conservative: an agent may run tests,
# compilers, or browser tooling in addition to the model client itself.
_AUTO_CONCURRENCY_CPU_THREADS_PER_AGENT = 4
_AUTO_CONCURRENCY_MEMORY_BYTES_PER_AGENT = 4 * 1024**3


def _acp_session_is_read_only(focus: Any, running_entry: Any | None) -> bool:
    """Return the authority mode for an ACP dispatch.

    Completion auditors are always read-only, independently of duplicate
    preflight state.  This matters for ACP backends with native tools (most
    notably the subscription Codex CLI), where the action-policy catalog
    cannot constrain the subprocess sandbox.
    """
    return (
        str(getattr(focus, "name", "")).casefold() == AUDITOR_FOCUS_NAME
        or bool(
            running_entry
            and getattr(running_entry, "duplicate_preflight", False)
        )
    )


def _acp_text_activity_detail(
    payload: dict[str, Any],
    *,
    read_only_preflight: bool,
) -> str:
    """Build in-memory ACP speech detail without losing a result envelope."""

    text = str(payload.get("text", ""))
    extracted_result = payload.get("duplicate_preflight_result")
    if read_only_preflight and extracted_result is not None:
        envelope = format_duplicate_preflight_result(extracted_result)
        if envelope is not None:
            return f"{envelope}\n{text}"
    return text[:2000]


def _available_memory_bytes() -> int | None:
    """Return Linux ``MemAvailable`` bytes, or ``None`` when unavailable."""
    try:
        with open("/proc/meminfo", encoding="utf-8") as meminfo:
            for line in meminfo:
                if line.startswith("MemAvailable:"):
                    return int(line.split()[1]) * 1024
    except (OSError, ValueError, IndexError):
        pass
    return None


_AGENT_LOG_STEM_RE = re.compile(r"[^A-Za-z0-9._-]+")


def _agent_log_issue_stem(issue_identifier: str) -> str:
    """Return a filesystem-safe stem for per-dispatch agent log filenames."""
    stem = _AGENT_LOG_STEM_RE.sub("_", str(issue_identifier or "").strip())
    stem = stem.strip("._-")
    return stem or "issue"


def _agent_log_path(log_dir: str, issue_identifier: str, ts: str | None = None) -> str:
    """Return a per-dispatch agent log path with a safe basename."""
    os.makedirs(log_dir, exist_ok=True)
    stamp = ts or datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    return os.path.join(log_dir, f"{_agent_log_issue_stem(issue_identifier)}__{stamp}.jsonl")


def _error_class_for_tracker_exc(exc: BaseException) -> str:
    """Classify a tracker/project exception for error_watcher dedup.

    Returned values match the documented classes used by the error
    watcher fingerprint:
      - "tracker_timeout"      — TrackerTimeoutError (subprocess timeout)
      - "tracker_not_configured" — TrackerNotConfiguredError
      - "tracker_auth_failed"  — TrackerAuthError (401/403 credential error)
      - "tracker_failed"       — generic TrackerError
      - "project_error"        — ProjectError fallback

    The returned class collapses every report with the same class to one
    task in the dedup window, regardless of which project/subcommand
    surfaced the failure.
    """
    if isinstance(exc, TrackerTimeoutError):
        return "tracker_timeout"
    if isinstance(exc, TrackerNotConfiguredError):
        return "tracker_not_configured"
    if isinstance(exc, TrackerAuthError):
        return "tracker_auth_failed"
    if isinstance(exc, TrackerStateBranchMissingError):
        return "tracker_state_branch_missing"
    if isinstance(exc, TrackerStateBranchFetchError):
        return "tracker_state_branch_fetch"
    if isinstance(exc, TrackerError):
        return "tracker_failed"
    return "project_error"


